1	// Package trailers provides parsing and formatting for Entire commit message trailers.
2	// Trailers are key-value metadata appended to git commit messages following the
3	// git trailer convention (key: value format after a blank line).
4	package trailers
5	
6	import (
7		"fmt"
8		"regexp"
9		"strings"
10	
11		checkpointID "github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
12	)
13	
14	// Trailer key constants used in commit messages.
15	const (
16		// MetadataTrailerKey points to the metadata directory within a commit tree.
17		MetadataTrailerKey = "Entire-Metadata"
18	
19		// MetadataTaskTrailerKey points to the task metadata directory for subagent checkpoints.
20		MetadataTaskTrailerKey = "Entire-Metadata-Task"
21	
22		// StrategyTrailerKey indicates which strategy created the commit.
23		StrategyTrailerKey = "Entire-Strategy"
24	
25		// BaseCommitTrailerKey links shadow commits to their base code commit.
26		BaseCommitTrailerKey = "Base-Commit"
27	
28		// SessionTrailerKey identifies which session created a commit.
29		SessionTrailerKey = "Entire-Session"
30	
31		// CondensationTrailerKey identifies the condensation ID for a commit (legacy).
32		CondensationTrailerKey = "Entire-Condensation"
33	
34		// SourceRefTrailerKey links code commits to their metadata on a shadow/metadata branch.
35		// Format: "<branch>@<commit-hash>" e.g. "entire/metadata@abc123def456"
36		SourceRefTrailerKey = "Entire-Source-Ref"
37	
38		// CheckpointTrailerKey links commits to their checkpoint metadata on entire/checkpoints/v1.
39		// Format: 12 hex characters e.g. "a3b2c4d5e6f7"
40		// This trailer survives git amend and rebase operations.
41		CheckpointTrailerKey = "Entire-Checkpoint"
42	
43		// EphemeralBranchTrailerKey identifies the shadow branch that a checkpoint originated from.
44		// Used in manual-commit strategy checkpoint commits on entire/checkpoints/v1 branch.
45		// Format: full branch name e.g. "entire/2b4c177"
46		EphemeralBranchTrailerKey = "Ephemeral-branch"
47	
48		// AgentTrailerKey identifies the agent that created a checkpoint.
49		// Format: human-readable agent name e.g. "Claude Code", "Cursor"
50		AgentTrailerKey = "Entire-Agent"
51	)
52	
53	// Pre-compiled regexes for trailer parsing.
54	var (
55		strategyTrailerRegex     = regexp.MustCompile(StrategyTrailerKey + `:\s*(.+)`)
56		metadataTrailerRegex     = regexp.MustCompile(MetadataTrailerKey + `:\s*(.+)`)
57		taskMetadataTrailerRegex = regexp.MustCompile(MetadataTaskTrailerKey + `:\s*(.+)`)
58		baseCommitTrailerRegex   = regexp.MustCompile(BaseCommitTrailerKey + `:\s*([a-f0-9]{40})`)
59		condensationTrailerRegex = regexp.MustCompile(CondensationTrailerKey + `:\s*(.+)`)
60		sessionTrailerRegex      = regexp.MustCompile(SessionTrailerKey + `:\s*(.+)`)
61		checkpointTrailerRegex   = regexp.MustCompile(CheckpointTrailerKey + `:\s*(` + checkpointID.Pattern + `)(?:\s|$)`)
62	)
63	
64	// ParseStrategy extracts strategy from commit message.
65	// Returns the strategy name and true if found, empty string and false otherwise.
66	func ParseStrategy(commitMessage string) (string, bool) {
67		matches := strategyTrailerRegex.FindStringSubmatch(commitMessage)
68		if len(matches) > 1 {
69			return strings.TrimSpace(matches[1]), true
70		}
71		return "", false
72	}
73	
74	// ParseMetadata extracts metadata dir from commit message.
75	// Returns the metadata directory and true if found, empty string and false otherwise.
76	func ParseMetadata(commitMessage string) (string, bool) {
77		matches := metadataTrailerRegex.FindStringSubmatch(commitMessage)
78		if len(matches) > 1 {
79			return strings.TrimSpace(matches[1]), true
80		}
81		return "", false
82	}
83	
84	// ParseTaskMetadata extracts task metadata dir from commit message.
85	// Returns the task metadata directory and true if found, empty string and false otherwise.
86	func ParseTaskMetadata(commitMessage string) (string, bool) {
87		matches := taskMetadataTrailerRegex.FindStringSubmatch(commitMessage)
88		if len(matches) > 1 {
89			return strings.TrimSpace(matches[1]), true
90		}
91		return "", false
92	}
93	
94	// ParseBaseCommit extracts the base commit SHA from a commit message.
95	// Returns the full SHA and true if found, empty string and false otherwise.
96	func ParseBaseCommit(commitMessage string) (string, bool) {
97		matches := baseCommitTrailerRegex.FindStringSubmatch(commitMessage)
98		if len(matches) > 1 {
99			return matches[1], true
100		}
101		return "", false
102	}
103	
104	// ParseCondensation extracts the condensation ID from a commit message.
105	// Returns the condensation ID and true if found, empty string and false otherwise.
106	func ParseCondensation(commitMessage string) (string, bool) {
107		matches := condensationTrailerRegex.FindStringSubmatch(commitMessage)
108		if len(matches) > 1 {
109			return strings.TrimSpace(matches[1]), true
110		}
111		return "", false
112	}
113	
114	// ParseSession extracts the session ID from a commit message.
115	// Returns the session ID and true if found, empty string and false otherwise.
116	// Note: If multiple Entire-Session trailers exist, this returns only the first one.
117	// Use ParseAllSessions to get all session IDs.
118	func ParseSession(commitMessage string) (string, bool) {
119		matches := sessionTrailerRegex.FindStringSubmatch(commitMessage)
120		if len(matches) > 1 {
121			return strings.TrimSpace(matches[1]), true
122		}
123		return "", false
124	}
125	
126	// ParseCheckpoint extracts the checkpoint ID from a commit message.
127	// Returns the CheckpointID and true if found, empty ID and false otherwise.
128	func ParseCheckpoint(commitMessage string) (checkpointID.CheckpointID, bool) {
129		matches := checkpointTrailerRegex.FindStringSubmatch(commitMessage)
130		if len(matches) > 1 {
131			idStr := strings.TrimSpace(matches[1])
132			// Validate it's a proper checkpoint ID
133			if cpID, err := checkpointID.NewCheckpointID(idStr); err == nil {
134				return cpID, true
135			}
136		}
137		return checkpointID.EmptyCheckpointID, false
138	}
139	
140	// ParseAllCheckpoints extracts all checkpoint IDs from a commit message.
141	// Returns a slice of CheckpointIDs (may be empty if none found).
142	// Duplicate IDs are deduplicated while preserving order.
143	// This is useful for squash merge commits that contain multiple Entire-Checkpoint trailers.
144	func ParseAllCheckpoints(commitMessage string) []checkpointID.CheckpointID {
145		matches := checkpointTrailerRegex.FindAllStringSubmatch(commitMessage, -1)
146		if len(matches) == 0 {
147			return nil
148		}
149	
150		seen := make(map[string]bool)
